                    tokio::time::sleep(Duration::from_secs(30)).await;
                    drop(socket);
                });
            }
        });
        tokio::time::sleep(Duration::from_millis(10)).await;

        let metrics = ServiceMetrics::new();
        let errors_total = metrics.errors_total.clone();
        let state = AppState {
            proxy: ProxyState {
                client: reqwest::Client::new(),
                upstream_url,
