1	//! HTTP proxy logic
2	//!
3	//! Receives inbound requests, strips hop-by-hop headers, delegates auth to the
4	//! provider, and forwards to the upstream URL. Returns the upstream response
5	//! verbatim (including error status codes from upstream).
6	
7	use axum::http::StatusCode;
8	use axum::response::{IntoResponse, Response};
9	use bytes::Bytes;
10	use futures_util::Stream;
11	use provider::Provider;
12	use std::pin::Pin;
13	use std::sync::Arc;
14	use std::task::{Context, Poll};
15	use std::time::{Duration, Instant};
16	use tokio::time::Sleep;
17	use tracing::{error, info, instrument, warn};
18	
19	/// Maximum retry attempts for upstream timeouts (spec: 2 retries = 3 total attempts)
20	const MAX_UPSTREAM_ATTEMPTS: u32 = 3;
21	
22	/// Fixed backoff between upstream timeout retries (spec: 100ms)
23	const UPSTREAM_RETRY_DELAY: Duration = Duration::from_millis(100);
24	
25	/// Maximum request body size (spec: 10 MiB)
26	pub const MAX_BODY_SIZE: usize = 10 * 1024 * 1024;
27	
28	/// Headers to strip before forwarding (hop-by-hop per RFC 2616 Section 13.5.1)
29	const HOP_BY_HOP_HEADERS: &[&str] = &[
30	    "connection",
31	    "keep-alive",
32	    "proxy-authenticate",
33	    "proxy-authorization",
34	    "te",
35	    "trailer",
36	    "transfer-encoding",
37	    "upgrade",
38	];
39	
40	/// Shared state passed to the proxy handler via axum State extractor
41	#[derive(Clone)]
42	pub struct ProxyState {
43	    pub client: reqwest::Client,
44	    pub upstream_url: String,
45	    pub provider: Arc<dyn Provider>,
46	    pub timeout: Duration,
47	    pub requests_total: Arc<std::sync::atomic::AtomicU64>,
48	    pub errors_total: Arc<std::sync::atomic::AtomicU64>,
49	    pub in_flight: Arc<std::sync::atomic::AtomicU64>,
50	    /// Maximum failover attempts for quota exhaustion. Equals pool size in OAuth
51	    /// mode (each attempt uses a different account). Set to 1 in passthrough mode
52	    /// (no failover, just forward the error).
53	    pub max_failover_attempts: usize,
54	}
55	
56	/// RAII guard that records OTel span attributes when dropped, ensuring every
57	/// exit path from proxy_request produces a complete span. When OTel is disabled
58	/// (no OpenTelemetryLayer in subscriber), all set_attribute calls are no-ops.
59	struct SpanRecorder {
60	    method: String,
61	    path: String,
62	    server_address: String,
63	    request_id: String,
64	    pool_mode: String,
65	    status_code: u16,
66	    account_id: Option<String>,
67	    error_type: Option<&'static str>,
68	    failover_attempt: usize,
69	}
70	
71	impl Drop for SpanRecorder {
72	    fn drop(&mut self) {
73	        crate::telemetry::record_span(
74	            &self.method,
75	            &self.path,
76	            &self.server_address,
77	            self.status_code,
78	            self.account_id.as_deref(),
79	            self.error_type,
80	            self.failover_attempt,
81	            &self.request_id,
82	            &self.pool_mode,
83	        );
84	    }
85	}
86	
87	/// RAII guard that decrements the in-flight counter when dropped, ensuring the
88	/// counter stays accurate even if the handler returns early or panics.
89	struct InFlightGuard(Arc<std::sync::atomic::AtomicU64>);
90	
91	impl Drop for InFlightGuard {
92	    fn drop(&mut self) {
93	        self.0.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
94	    }
95	}
96	
97	// Wraps a byte stream with an idle timeout that resets on each received chunk.
98	// If no data arrives within the timeout window, the stream terminates cleanly
99	// (returns None). This protects against dead upstream connections mid-stream
100	// without killing healthy long-running SSE streams that send periodic data.
101	pin_project_lite::pin_project! {
102	    struct IdleTimeoutStream<S> {
103	        #[pin]
104	        inner: S,
105	        #[pin]
106	        deadline: Sleep,
107	        timeout: Duration,
108	        timed_out: bool,
109	    }
110	}
111	
112	impl<S> IdleTimeoutStream<S> {
113	    fn new(inner: S, timeout: Duration) -> Self {
114	        Self {
115	            inner,
116	            deadline: tokio::time::sleep(timeout),
117	            timeout,
118	            timed_out: false,
119	        }
120	    }
121	}
122	
123	impl<S, E> Stream for IdleTimeoutStream<S>
124	where
125	    S: Stream<Item = Result<Bytes, E>>,
126	    E: Into<Box<dyn std::error::Error + Send + Sync>>,
127	{
128	    type Item = Result<Bytes, Box<dyn std::error::Error + Send + Sync>>;
129	
130	    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
131	        let mut this = self.project();
132	
133	        if *this.timed_out {
134	            return Poll::Ready(None);
135	        }
136	
137	        if this.deadline.as_mut().poll(cx).is_ready() {
138	            *this.timed_out = true;
139	            warn!("upstream idle timeout after {}s", this.timeout.as_secs());
140	            return Poll::Ready(None);
141	        }
142	
143	        match this.inner.poll_next(cx) {
144	            Poll::Ready(Some(Ok(bytes))) => {
145	                this.deadline
146	                    .reset(tokio::time::Instant::now() + *this.timeout);
147	                Poll::Ready(Some(Ok(bytes)))
148	            }
149	            Poll::Ready(Some(Err(e))) => Poll::Ready(Some(Err(e.into()))),
150	            Poll::Ready(None) => Poll::Ready(None),
151	            Poll::Pending => Poll::Pending,
152	        }
153	    }
154	}
155	
156	/// JSON error response per spec: {"error":{"type":"proxy_error","message":"...","request_id":"req_..."}}
157	fn error_response(status: StatusCode, message: &str, request_id: &str) -> Response {
158	    let body = serde_json::json!({
159	        "error": {
160	            "type": "proxy_error",
161	            "message": message,
162	            "request_id": request_id,
163	        }
164	    });
165	    (
166	        status,
167	        [(axum::http::header::CONTENT_TYPE, "application/json")],
168	        body.to_string(),
169	    )
170	        .into_response()
171	}
172	
173	/// Proxy an inbound request to upstream with header injection, retries, and failover.
174	///
175	/// Retry strategy per spec: UpstreamTimeout gets 2 retries with 100ms fixed backoff.
176	/// Failover strategy: QuotaExceeded triggers account switch and re-send; Permanent
177	/// errors disable the account and return the error; Transient errors are returned.
178	#[instrument(skip_all, fields(request_id = %request_id, method = %request.method(), path = %request.uri().path()))]
179	pub async fn proxy_request(
180	    state: &ProxyState,
181	    request: axum::http::Request<axum::body::Body>,
182	    request_id: String,
183	) -> Response {
184	    let start = Instant::now();
185	    state
186	        .requests_total
187	        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
188	    state
189	        .in_flight
190	        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
191	    let _in_flight_guard = InFlightGuard(state.in_flight.clone());
192	
193	    let method = request.method().clone();
194	    let method_str = method.to_string();
195	    let uri = request.uri().clone();
196	    let path_str = uri.path().to_string();
197	    let pool_mode = if state.provider.needs_body() {
198	        "oauth"
199	    } else {
200	        "passthrough"
201	    };
202	
203	    // SpanRecorder sets OTel span attributes on drop — every exit path gets a
204	    // complete span regardless of how the function returns.
205	    let mut span_recorder = SpanRecorder {
206	        method: method_str.clone(),
207	        path: path_str,
208	        server_address: state.upstream_url.clone(),
209	        request_id: request_id.clone(),
210	        pool_mode: pool_mode.to_string(),
211	        status_code: 500, // default; overwritten before every return
212	        account_id: None,
213	        error_type: None,
214	        failover_attempt: 0,
215	    };
216	
217	    // Build the upstream URL by appending the request path and query
218	    let upstream_url = if let Some(pq) = uri.path_and_query() {
219	        format!("{}{}", state.upstream_url.trim_end_matches('/'), pq)
220	    } else {
221	        state.upstream_url.clone()
222	    };
223	
224	    // Collect original request headers, stripping hop-by-hop, host, and
225	    // content-length. Host carries the proxy's hostname — reqwest sets the
226	    // correct one from the upstream URL. Content-Length must be recalculated
227	    // by reqwest/hyper because OAuth mode re-serializes the body (system
228	    // prompt injection changes byte count). Forwarding the client's original
229	    // Content-Length causes a mismatch that Cloudflare rejects with 400.
230	    //
231	    // Uses append() instead of insert() to preserve multi-value headers
232	    // (e.g. multiple Cookie or Accept-Encoding values from the client).
233	    let mut original_headers = reqwest::header::HeaderMap::new();
234	    for (name, value) in request.headers() {
235	        if !is_hop_by_hop(name.as_str())
236	            && name != axum::http::header::HOST
237	            && name != axum::http::header::CONTENT_LENGTH
238	        {
239	            original_headers.append(name.clone(), value.clone());
240	        }
241	    }
242	
243	    // Read the request body
244	    let body_bytes = match axum::body::to_bytes(request.into_body(), MAX_BODY_SIZE).await {
245	        Ok(b) => b,
246	        Err(e) => {
247	            state
248	                .errors_total
249	                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
250	            error!(error = %e, "failed to read request body");
251	            let status = StatusCode::BAD_REQUEST;
252	            crate::metrics::record_request(
253	                status.as_u16(),
254	                &method_str,
255	                start.elapsed().as_secs_f64(),
256	            );
257	            crate::metrics::record_upstream_error("invalid_request");
258	            span_recorder.status_code = status.as_u16();
259	            return error_response(status, &format!("invalid request body: {e}"), &request_id);
260	        }
261	    };
262	
263	    // Parse body JSON once if the provider needs it (OAuth mode needs body for
264	    // system prompt injection). The parsed value is re-used across failover attempts.
265	    let parsed_body = if state.provider.needs_body() {
266	        match serde_json::from_slice::<serde_json::Value>(&body_bytes) {
267	            Ok(v) => Some(v),
268	            Err(e) => {
269	                state
270	                    .errors_total
271	                    .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
272	                let status = StatusCode::BAD_REQUEST;
273	                crate::metrics::record_request(
274	                    status.as_u16(),
275	                    &method_str,
276	                    start.elapsed().as_secs_f64(),
277	                );
278	                crate::metrics::record_upstream_error("invalid_request");
279	                span_recorder.status_code = status.as_u16();
280	                return error_response(status, &format!("Invalid JSON body: {e}"), &request_id);
281	            }
282	        }
283	    } else {
284	        None
285	    };
286	
287	    // Maximum failover attempts equals the pool size (each attempt uses a
288	    // different account). Passthrough mode uses 1 attempt (no failover).
289	    let max_failovers = state.max_failover_attempts;
290	
291	    for failover in 0..max_failovers {
292	        span_recorder.failover_attempt = failover;
293	
294	        // Start from original headers each attempt so provider injection is clean.
295	        // Without this, headers from a previous failed account (e.g. wrong Bearer
296	        // token) would carry over into the next attempt.
297	        let mut headers = original_headers.clone();
298	        let mut body_value = parsed_body.clone().unwrap_or(serde_json::Value::Null);
299	
300	        let account_id = match state
301	            .provider
302	            .prepare_request(&mut headers, &mut body_value)
303	            .await
304	        {
305	            Ok(id) => id,
306	            Err(e) => {
307	                state
308	                    .errors_total
309	                    .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
310	                let status = StatusCode::SERVICE_UNAVAILABLE;
311	                crate::metrics::record_request(
312	                    status.as_u16(),
313	                    &method_str,
314	                    start.elapsed().as_secs_f64(),
315	                );
316	                error!(error = %e, "provider prepare_request failed");
317	                span_recorder.status_code = status.as_u16();
318	                return error_response(status, &format!("provider error: {e}"), &request_id);
319	            }
320	        };
321	
322	        // Track the account used for this attempt in the span
323	        span_recorder.account_id = account_id.clone();
324	
325	        let final_body = if state.provider.needs_body() {
326	            serde_json::to_vec(&body_value)
327	                .unwrap_or_else(|_| body_bytes.to_vec())
328	                .into()
329	        } else {
330	            body_bytes.clone()
331	        };
332	
333	        // Timeout retry loop within this failover attempt
334	        let mut last_error_response = None;
335	
336	        for attempt in 0..MAX_UPSTREAM_ATTEMPTS {
337	            if attempt > 0 {
338	                warn!(attempt, "retrying after upstream timeout");
339	                tokio::time::sleep(UPSTREAM_RETRY_DELAY).await;
340	            }
341	
342	            let req = state
343	                .client
344	                .request(method.clone(), &upstream_url)
345	                .headers(headers.clone())
346	                .body(final_body.clone());
347	
348	            let send_result = tokio::time::timeout(state.timeout, req.send()).await;
349	            match send_result {
350	                Ok(Ok(upstream_response)) => {
351	                    let status = upstream_response.status();
352	
353	                    // For error responses that may need classification (quota/auth
354	                    // errors), buffer the body. For success or non-classifiable
355	                    // errors, stream directly.
356	                    if status.is_client_error() || status.is_server_error() {
357	                        if let Some(ref acct) = account_id {
358	                            // Buffer error body for classification
359	                            let resp_headers = upstream_response.headers().clone();
360	                            let error_body = upstream_response.bytes().await.unwrap_or_default();
361	                            let error_body_str = String::from_utf8_lossy(&error_body).to_string();
362	
363	                            let classification = state
364	                                .provider
365	                                .classify_error(status.as_u16(), &error_body_str);
366	
367	                            match classification {
368	                                provider::ErrorClassification::QuotaExceeded => {
369	                                    warn!(
370	                                        account_id = acct,
371	                                        failover, "quota exhausted, failing over to next account"
372	                                    );
373	                                    let _ = state.provider.report_error(acct, classification).await;
374	                                    crate::metrics::record_upstream_error("quota_exhausted");
375	                                    crate::metrics::record_pool_quota_exhaustion(acct);
376	                                    crate::metrics::record_pool_failover(acct, "quota_exhausted");
377	                                    crate::metrics::record_pool_account_status(
378	                                        acct,
379	                                        "cooling_down",
380	                                    );
381	                                    // Track for span in case this is the last failover
382	                                    span_recorder.error_type = Some("quota_exhausted");
383	                                    span_recorder.status_code = status.as_u16();
384	                                    // Store response in case this is the last failover
385	                                    last_error_response = Some((status, resp_headers, error_body));
386	                                    break; // exit timeout retry loop, continue failover loop
387	                                }
388	                                provider::ErrorClassification::Permanent => {
389	                                    warn!(account_id = acct, "permanent error, disabling account");
390	                                    let _ = state.provider.report_error(acct, classification).await;
391	                                    crate::metrics::record_upstream_error("permanent");
392	                                    crate::metrics::record_pool_account_status(acct, "disabled");
393	                                    // Return error to client immediately
394	                                    let elapsed = start.elapsed();
395	                                    crate::metrics::record_request(
396	                                        status.as_u16(),
397	                                        &method_str,
398	                                        elapsed.as_secs_f64(),
399	                                    );
400	                                    state
401	                                        .errors_total
402	                                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
403	                                    span_recorder.error_type = Some("permanent");
404	                                    span_recorder.status_code = status.as_u16();
405	                                    return build_buffered_response(
406	                                        status,
407	                                        &resp_headers,
408	                                        error_body,
409	                                    );
410	                                }
411	                                provider::ErrorClassification::Transient => {
412	                                    // Return error to client (existing timeout retry
413	                                    // handles transport-level retries)
414	                                    let elapsed = start.elapsed();
415	                                    crate::metrics::record_request(
416	                                        status.as_u16(),
417	                                        &method_str,
418	                                        elapsed.as_secs_f64(),
419	                                    );
420	                                    info!(
421	                                        status = status.as_u16(),
422	                                        latency_ms = elapsed.as_millis() as u64,
423	                                        "request completed (transient error)"
424	                                    );
425	                                    span_recorder.error_type = Some("transient");
426	                                    span_recorder.status_code = status.as_u16();
427	                                    return build_buffered_response(
428	                                        status,
429	                                        &resp_headers,
430	                                        error_body,
431	                                    );
432	                                }
433	                            }
434	                        } else {
435	                            // Passthrough mode: no account, stream error response directly
436	                            let resp_headers = upstream_response.headers().clone();
437	                            let elapsed = start.elapsed();
438	                            crate::metrics::record_request(
439	                                status.as_u16(),
440	                                &method_str,
441	                                elapsed.as_secs_f64(),
442	                            );
443	                            info!(
444	                                status = status.as_u16(),
445	                                latency_ms = elapsed.as_millis() as u64,
446	                                "request completed"
447	                            );
448	                            span_recorder.status_code = status.as_u16();
449	                            return build_streaming_response(
450	                                status,
451	                                &resp_headers,
452	                                upstream_response,
453	                                &request_id,
454	                                state.timeout,
455	                            );
456	                        }
457	                    }
458	
459	                    // Success: stream the response body. This is critical for SSE
460	                    // (Server-Sent Events) from the Anthropic API where Claude
461	                    // responses are streamed in real-time.
462	                    let resp_headers = upstream_response.headers().clone();
463	                    let elapsed = start.elapsed();
464	                    crate::metrics::record_request(
465	                        status.as_u16(),
466	                        &method_str,
467	                        elapsed.as_secs_f64(),
468	                    );
469	                    info!(
470	                        status = status.as_u16(),
471	                        latency_ms = elapsed.as_millis() as u64,
472	                        "request completed"
473	                    );
474	                    span_recorder.status_code = status.as_u16();
475	                    span_recorder.error_type = None;
476	                    return build_streaming_response(
477	                        status,
478	                        &resp_headers,
479	                        upstream_response,
480	                        &request_id,
481	                        state.timeout,
482	                    );
483	                }
484	                Ok(Err(e)) => {
485	                    state
486	                        .errors_total
487	                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
488	                    let err_status = StatusCode::BAD_GATEWAY;
489	                    crate::metrics::record_request(
490	                        err_status.as_u16(),
491	                        &method_str,
492	                        start.elapsed().as_secs_f64(),
493	                    );
494	                    crate::metrics::record_upstream_error("connection");
495	                    error!(error = %e, "upstream request failed");
496	                    span_recorder.status_code = err_status.as_u16();
497	                    return error_response(
498	                        err_status,
499	                        &format!("upstream error: {e}"),
500	                        &request_id,
501	                    );
502	                }
503	                Err(_elapsed) => {
504	                    if attempt < MAX_UPSTREAM_ATTEMPTS - 1 {
505	                        continue;
506	                    }
507	                    state
508	                        .errors_total
509	                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
510	                    let err_status = StatusCode::GATEWAY_TIMEOUT;
511	                    crate::metrics::record_request(
512	                        err_status.as_u16(),
513	                        &method_str,
514	                        start.elapsed().as_secs_f64(),
515	                    );
516	                    crate::metrics::record_upstream_error("timeout");
517	                    error!(
518	                        timeout_secs = state.timeout.as_secs(),
519	                        attempts = MAX_UPSTREAM_ATTEMPTS,
520	                        "upstream response timeout after all retries"
521	                    );
522	                    span_recorder.status_code = err_status.as_u16();
523	                    return error_response(
524	                        err_status,
525	                        &format!(
526	                            "upstream response timeout after {}s ({MAX_UPSTREAM_ATTEMPTS} attempts)",
527	                            state.timeout.as_secs()
528	                        ),
529	                        &request_id,
530	                    );
531	                }
532	            }
533	        }
534	
535	        // If we broke out of the timeout loop due to quota exhaustion but have
536	        // more failover attempts, continue to the next account
537	        if last_error_response.is_some() && failover < max_failovers - 1 {
538	            // Reset error_type for next attempt — success on next account
539	            // will clear it via the success path
540	            span_recorder.error_type = None;
541	            continue;
542	        }
543	
544	        // Last failover attempt exhausted — return the last error response.
545	        // span_recorder already has error_type/status_code from the break above.
546	        if let Some((status, resp_headers, error_body)) = last_error_response {
547	            state
548	                .errors_total
549	                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
550	            crate::metrics::record_request(
551	                status.as_u16(),
552	                &method_str,
553	                start.elapsed().as_secs_f64(),
554	            );
555	            return build_buffered_response(status, &resp_headers, error_body);
556	        }
557	    }
558	
559	    unreachable!("failover loop must return on every code path")
560	}
561	
562	/// Build a response from a buffered error body (used after error classification).
563	fn build_buffered_response(
564	    status: StatusCode,
565	    resp_headers: &reqwest::header::HeaderMap,
566	    body: axum::body::Bytes,
567	) -> Response {
568	    let mut response = Response::builder().status(status);
569	    for (name, value) in resp_headers {
570	        if !is_hop_by_hop(name.as_str()) {
571	            response = response.header(name, value);
572	        }
573	    }
574	    response
575	        .body(axum::body::Body::from(body))
576	        .unwrap_or_else(|e| {
577	            error_response(
578	                StatusCode::INTERNAL_SERVER_ERROR,
579	                &format!("response build error: {e}"),
580	                "",
581	            )
582	        })
583	}
584	
585	/// Build a streaming response (used for success and passthrough error responses).
586	/// Wraps the upstream byte stream with an idle timeout that terminates the stream
587	/// if no data arrives within the given duration.
588	fn build_streaming_response(
589	    status: StatusCode,
590	    resp_headers: &reqwest::header::HeaderMap,
591	    upstream_response: reqwest::Response,
592	    request_id: &str,
593	    idle_timeout: Duration,
594	) -> Response {
595	    let mut response = Response::builder().status(status);
596	    for (name, value) in resp_headers {
597	        if !is_hop_by_hop(name.as_str()) {
598	            response = response.header(name, value);
599	        }
600	    }
601	    let idle_stream = IdleTimeoutStream::new(upstream_response.bytes_stream(), idle_timeout);
602	    response
603	        .body(axum::body::Body::from_stream(idle_stream))
604	        .unwrap_or_else(|e| {
605	            error_response(
606	                StatusCode::INTERNAL_SERVER_ERROR,
607	                &format!("response build error: {e}"),
608	                request_id,
609	            )
610	        })
611	}
612	
613	/// Check if a header is hop-by-hop (should be stripped before forwarding)
614	pub fn is_hop_by_hop(name: &str) -> bool {
615	    HOP_BY_HOP_HEADERS
616	        .iter()
617	        .any(|h| h.eq_ignore_ascii_case(name))
618	}
619	
620	#[cfg(test)]
621	mod tests {
622	    use super::*;
623	
624	    #[test]
625	    fn test_hop_by_hop_detection_all_eight_headers() {
626	        // All 8 spec-defined hop-by-hop headers (RFC 2616 Section 13.5.1)
627	        assert!(is_hop_by_hop("connection"));
628	        assert!(is_hop_by_hop("keep-alive"));
629	        assert!(is_hop_by_hop("proxy-authenticate"));
630	        assert!(is_hop_by_hop("proxy-authorization"));
631	        assert!(is_hop_by_hop("te"));
632	        assert!(is_hop_by_hop("trailer"));
633	        assert!(is_hop_by_hop("transfer-encoding"));
634	        assert!(is_hop_by_hop("upgrade"));
635	
636	        // Case-insensitive detection (all 8 headers)
637	        assert!(is_hop_by_hop("Connection"));
638	        assert!(is_hop_by_hop("TRANSFER-ENCODING"));
639	        assert!(is_hop_by_hop("Keep-Alive"));
640	        assert!(is_hop_by_hop("Proxy-Authenticate"));
641	        assert!(is_hop_by_hop("Proxy-Authorization"));
642	        assert!(is_hop_by_hop("TE"));
643	        assert!(is_hop_by_hop("Trailer"));
644	        assert!(is_hop_by_hop("Upgrade"));
645	
646	        // Non-hop-by-hop headers must not match
647	        assert!(!is_hop_by_hop("Content-Type"));
648	        assert!(!is_hop_by_hop("Authorization"));
649	        assert!(!is_hop_by_hop("X-Custom-Header"));
650	        assert!(!is_hop_by_hop("Accept-Encoding"));
651	    }
652	
653	    #[tokio::test]
654	    async fn test_error_response_format() {
655	        let resp = error_response(
656	            StatusCode::GATEWAY_TIMEOUT,
657	            "upstream timeout after 60s",
658	            "req_abc123",
659	        );
660	        assert_eq!(resp.status(), StatusCode::GATEWAY_TIMEOUT);
661	
662	        // Verify the response body matches the spec JSON format:
663	        // {"error":{"type":"proxy_error","message":"...","request_id":"..."}}
664	        let body = resp.into_body();
665	        let bytes = axum::body::to_bytes(body, 1024 * 1024).await.unwrap();
666	        let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
667	        assert_eq!(json["error"]["type"], "proxy_error");
668	        assert_eq!(json["error"]["message"], "upstream timeout after 60s");
669	        assert_eq!(json["error"]["request_id"], "req_abc123");
670	    }
671	
672	    #[tokio::test]
673	    async fn test_error_response_content_type() {
674	        let resp = error_response(StatusCode::BAD_GATEWAY, "upstream error", "req_test123");
675	        let content_type = resp
676	            .headers()
677	            .get("content-type")
678	            .unwrap()
679	            .to_str()
680	            .unwrap();
681	        assert_eq!(
682	            content_type, "application/json",
683	            "error responses must have application/json Content-Type"
684	        );
685	    }
686	
687	    #[test]
688	    fn test_in_flight_guard_decrements_on_drop() {
689	        let counter = Arc::new(std::sync::atomic::AtomicU64::new(0));
690	        counter.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
691	        assert_eq!(counter.load(std::sync::atomic::Ordering::Relaxed), 1);
692	
693	        {
694	            let _guard = InFlightGuard(counter.clone());
695	        }
696	        // Guard dropped, counter should be decremented
697	        assert_eq!(counter.load(std::sync::atomic::Ordering::Relaxed), 0);
698	    }
699	
700	    #[test]
701	    fn test_in_flight_guard_multiple_concurrent() {
702	        let counter = Arc::new(std::sync::atomic::AtomicU64::new(0));
703	
704	        // Simulate 3 in-flight requests
705	        counter.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
706	        let _g1 = InFlightGuard(counter.clone());
707	        counter.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
708	        let _g2 = InFlightGuard(counter.clone());
709	        counter.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
710	        let _g3 = InFlightGuard(counter.clone());
711	        assert_eq!(counter.load(std::sync::atomic::Ordering::Relaxed), 3);
712	
713	        drop(_g1);
714	        assert_eq!(counter.load(std::sync::atomic::Ordering::Relaxed), 2);
715	
716	        drop(_g2);
717	        assert_eq!(counter.load(std::sync::atomic::Ordering::Relaxed), 1);
718	
719	        drop(_g3);
720	        assert_eq!(counter.load(std::sync::atomic::Ordering::Relaxed), 0);
721	    }
722	}
