1	//! Pool state machine and round-robin account selection
2	//!
3	//! The pool holds per-account status (Available, CoolingDown, Disabled) and selects
4	//! accounts round-robin. The credential store is the single source of truth for
5	//! token data; the pool reads credentials at selection time.
6	//!
7	//! Cooldown transitions happen automatically: when a CoolingDown account is checked
8	//! and its cooldown has expired, it transitions back to Available without explicit action.
9	
10	use std::collections::HashMap;
11	use std::sync::atomic::{AtomicUsize, Ordering};
12	use std::time::{Duration, Instant};
13	
14	use anthropic_auth::CredentialStore;
15	use provider::ErrorClassification;
16	use tokio::sync::RwLock;
17	use tracing::{debug, info, warn};
18	
19	use crate::error::{Error, Result};
20	
21	/// Runtime status of a pool account.
22	///
23	/// Transitions:
24	/// - Available → CoolingDown (quota exhausted 429)
25	/// - Available → Disabled (401/403 permanent error)
26	/// - CoolingDown → Available (cooldown expired)
27	/// - CoolingDown → Disabled (refresh failure while cooling)
28	/// - Disabled → (removed by admin)
29	#[derive(Debug, Clone)]
30	pub enum AccountStatus {
31	    Available,
32	    CoolingDown { until: Instant },
33	    Disabled,
34	}
35	
36	impl AccountStatus {
37	    /// Status label for health/logging.
38	    pub fn label(&self) -> &'static str {
39	        match self {
40	            AccountStatus::Available => "available",
41	            AccountStatus::CoolingDown { .. } => "cooling_down",
42	            AccountStatus::Disabled => "disabled",
43	        }
44	    }
45	}
46	
47	/// A selected account with its access token, ready for a request.
48	#[derive(Debug)]
49	pub struct SelectedAccount {
50	    pub id: String,
51	    pub access_token: String,
52	}
53	
54	/// Subscription pool managing multiple OAuth accounts.
55	///
56	/// Uses an `AtomicUsize` for the round-robin index and `RwLock` for the account
57	/// list and status map. The credential store is shared via `Arc` and provides
58	/// the token data.
59	pub struct Pool {
60	    account_ids: RwLock<Vec<String>>,
61	    statuses: RwLock<HashMap<String, AccountStatus>>,
62	    next_index: AtomicUsize,
63	    cooldown_duration: Duration,
64	    credential_store: std::sync::Arc<CredentialStore>,
65	    http_client: reqwest::Client,
66	}
67	
68	impl Pool {
69	    /// Create a new pool backed by the given credential store.
70	    ///
71	    /// `account_ids` is the initial list of accounts to manage. Each must have
72	    /// a corresponding entry in the credential store. Accounts start as Available.
73	    pub fn new(
74	        account_ids: Vec<String>,
75	        cooldown_duration: Duration,
76	        credential_store: std::sync::Arc<CredentialStore>,
77	        http_client: reqwest::Client,
78	    ) -> Self {
79	        let statuses: HashMap<String, AccountStatus> = account_ids
80	            .iter()
81	            .map(|id| (id.clone(), AccountStatus::Available))
82	            .collect();
83	        info!(accounts = account_ids.len(), "pool initialized");
84	        Self {
85	            account_ids: RwLock::new(account_ids),
86	            statuses: RwLock::new(statuses),
87	            next_index: AtomicUsize::new(0),
88	            cooldown_duration,
89	            credential_store,
90	            http_client,
91	        }
92	    }
93	
94	    /// Select the next available account via round-robin.
95	    ///
96	    /// Scans all accounts starting from `next_index`. Expired cooldowns are
97	    /// transitioned to Available automatically. If a selected account's token
98	    /// expires within 60 seconds, attempts an inline refresh; on failure, the
99	    /// account is disabled and the scan continues.
100	    ///
101	    /// Returns `PoolExhausted` with pool counts if no account is available.
102	    pub async fn select(&self) -> Result<SelectedAccount> {
103	        let ids = self.account_ids.read().await;
104	        let n = ids.len();
105	        if n == 0 {
106	            return Err(Error::PoolExhausted(
107	                self.exhausted_message(0, 0, 0, 0).await,
108	            ));
109	        }
110	
111	        let start = self.next_index.fetch_add(1, Ordering::Relaxed) % n;
112	
113	        for offset in 0..n {
114	            let idx = (start + offset) % n;
115	            let id = &ids[idx];
116	
117	            // Check and possibly transition status
118	            let available = {
119	                let mut statuses = self.statuses.write().await;
120	                let status = statuses.get(id);
121	                match status {
122	                    Some(AccountStatus::Available) => true,
123	                    Some(AccountStatus::CoolingDown { until }) => {
124	                        if Instant::now() >= *until {
125	                            info!(account_id = id, "cooldown expired, account available again");
126	                            statuses.insert(id.clone(), AccountStatus::Available);
127	                            true
128	                        } else {
129	                            false
130	                        }
131	                    }
132	                    Some(AccountStatus::Disabled) | None => false,
133	                }
134	            };
135	
136	            if !available {
137	                continue;
138	            }
139	
140	            // Get credential from store
141	            let credential = match self.credential_store.get(id).await {
142	                Some(c) => c,
143	                None => {
144	                    warn!(
145	                        account_id = id,
146	                        "account in pool but not in credential store, disabling"
147	                    );
148	                    self.statuses
149	                        .write()
150	                        .await
151	                        .insert(id.clone(), AccountStatus::Disabled);
152	                    continue;
153	                }
154	            };
155	
156	            // Request-time refresh: if token expires within 60 seconds, refresh inline
157	            let now_millis = std::time::SystemTime::now()
158	                .duration_since(std::time::UNIX_EPOCH)
159	                .unwrap_or_default()
160	                .as_millis() as u64;
161	            let refresh_threshold_millis = 60_000;
162	
163	            if credential.expires <= now_millis + refresh_threshold_millis {
164	                debug!(
165	                    account_id = id,
166	                    "token expiring soon, attempting inline refresh"
167	                );
168	                match anthropic_auth::refresh_token(&self.http_client, &credential.refresh).await {
169	                    Ok(token_response) => {
170	                        let new_expires = now_millis + (token_response.expires_in * 1000);
171	                        if let Err(e) = self
172	                            .credential_store
173	                            .update_token(
174	                                id,
175	                                token_response.access_token.clone(),
176	                                token_response.refresh_token,
177	                                new_expires,
178	                            )
179	                            .await
180	                        {
181	                            warn!(account_id = id, error = %e, "failed to persist refreshed token");
182	                        }
183	                        info!(account_id = id, "inline token refresh succeeded");
184	                        return Ok(SelectedAccount {
185	                            id: id.clone(),
186	                            access_token: token_response.access_token,
187	                        });
188	                    }
189	                    Err(e) => {
190	                        warn!(account_id = id, error = %e, "inline refresh failed, disabling account");
191	                        self.statuses
192	                            .write()
193	                            .await
194	                            .insert(id.clone(), AccountStatus::Disabled);
195	                        continue;
196	                    }
197	                }
198	            }
199	
200	            return Ok(SelectedAccount {
201	                id: id.clone(),
202	                access_token: credential.access,
203	            });
204	        }
205	
206	        // All accounts exhausted
207	        let (total, available, cooling, disabled) = self.count_statuses().await;
208	        Err(Error::PoolExhausted(
209	            self.exhausted_message(total, available, cooling, disabled)
210	                .await,
211	        ))
212	    }
213	
214	    /// Report an error classification for an account, triggering state transitions.
215	    ///
216	    /// - QuotaExceeded → CoolingDown for cooldown_duration
217	    /// - Permanent → Disabled
218	    /// - Transient → no change
219	    pub async fn report_error(&self, account_id: &str, classification: ErrorClassification) {
220	        let mut statuses = self.statuses.write().await;
221	        match classification {
222	            ErrorClassification::QuotaExceeded => {
223	                let until = Instant::now() + self.cooldown_duration;
224	                info!(
225	                    account_id,
226	                    cooldown_secs = self.cooldown_duration.as_secs(),
227	                    "account entering cooldown (quota exhausted)"
228	                );
229	                statuses.insert(account_id.to_string(), AccountStatus::CoolingDown { until });
230	            }
231	            ErrorClassification::Permanent => {
232	                warn!(account_id, "account disabled (permanent error)");
233	                statuses.insert(account_id.to_string(), AccountStatus::Disabled);
234	            }
235	            ErrorClassification::Transient => {
236	                debug!(account_id, "transient error, no pool action");
237	            }
238	        }
239	    }
240	
241	    /// Add a new account to the pool. Starts as Available.
242	    pub async fn add_account(&self, account_id: String) {
243	        let mut ids = self.account_ids.write().await;
244	        if !ids.contains(&account_id) {
245	            ids.push(account_id.clone());
246	        }
247	        self.statuses
248	            .write()
249	            .await
250	            .insert(account_id.clone(), AccountStatus::Available);
251	        info!(account_id, "account added to pool");
252	    }
253	
254	    /// Remove an account from the pool.
255	    pub async fn remove_account(&self, account_id: &str) {
256	        let mut ids = self.account_ids.write().await;
257	        ids.retain(|id| id != account_id);
258	        self.statuses.write().await.remove(account_id);
259	        info!(account_id, "account removed from pool");
260	    }
261	
262	    /// Pool health summary for the health endpoint.
263	    ///
264	    /// Returns a JSON value with per-account status and overall pool health.
265	    /// Status mapping: all available → healthy, some available → degraded,
266	    /// none available → unhealthy.
267	    pub async fn health(&self) -> serde_json::Value {
268	        let ids = self.account_ids.read().await;
269	        let statuses = self.statuses.read().await;
270	        let now = Instant::now();
271	
272	        let mut accounts = Vec::new();
273	        let mut available_count = 0usize;
274	        let mut cooling_count = 0usize;
275	        let mut disabled_count = 0usize;
276	
277	        for id in ids.iter() {
278	            let status = statuses.get(id);
279	            match status {
280	                Some(AccountStatus::Available) => {
281	                    available_count += 1;
282	                    accounts.push(serde_json::json!({
283	                        "id": id,
284	                        "status": "available"
285	                    }));
286	                }
287	                Some(AccountStatus::CoolingDown { until }) => {
288	                    let remaining = if *until > now {
289	                        (*until - now).as_secs()
290	                    } else {
291	                        0
292	                    };
293	                    cooling_count += 1;
294	                    accounts.push(serde_json::json!({
295	                        "id": id,
296	                        "status": "cooling_down",
297	                        "cooldown_remaining_secs": remaining
298	                    }));
299	                }
300	                Some(AccountStatus::Disabled) => {
301	                    disabled_count += 1;
302	                    accounts.push(serde_json::json!({
303	                        "id": id,
304	                        "status": "disabled"
305	                    }));
306	                }
307	                None => {
308	                    disabled_count += 1;
309	                    accounts.push(serde_json::json!({
310	                        "id": id,
311	                        "status": "disabled"
312	                    }));
313	                }
314	            }
315	        }
316	
317	        let total = ids.len();
318	        let pool_status = if available_count == total && total > 0 {
319	            "healthy"
320	        } else if available_count > 0 {
321	            "degraded"
322	        } else {
323	            "unhealthy"
324	        };
325	
326	        serde_json::json!({
327	            "status": pool_status,
328	            "accounts_total": total,
329	            "accounts_available": available_count,
330	            "accounts_cooling_down": cooling_count,
331	            "accounts_disabled": disabled_count,
332	            "accounts": accounts
333	        })
334	    }
335	
336	    /// Get the credential store reference (for background refresh).
337	    pub fn credential_store(&self) -> &std::sync::Arc<CredentialStore> {
338	        &self.credential_store
339	    }
340	
341	    /// Get the HTTP client reference (for background refresh).
342	    pub fn http_client(&self) -> &reqwest::Client {
343	        &self.http_client
344	    }
345	
346	    /// Get a snapshot of all account IDs.
347	    pub async fn account_ids(&self) -> Vec<String> {
348	        self.account_ids.read().await.clone()
349	    }
350	
351	    /// Set an account's status directly (used by background refresh on failure).
352	    pub async fn set_status(&self, account_id: &str, status: AccountStatus) {
353	        self.statuses
354	            .write()
355	            .await
356	            .insert(account_id.to_string(), status);
357	    }
358	
359	    /// Count accounts by status.
360	    async fn count_statuses(&self) -> (usize, usize, usize, usize) {
361	        let ids = self.account_ids.read().await;
362	        let statuses = self.statuses.read().await;
363	        let now = Instant::now();
364	        let total = ids.len();
365	        let mut available = 0usize;
366	        let mut cooling = 0usize;
367	        let mut disabled = 0usize;
368	
369	        for id in ids.iter() {
370	            match statuses.get(id) {
371	                Some(AccountStatus::Available) => available += 1,
372	                Some(AccountStatus::CoolingDown { until }) => {
373	                    if now >= *until {
374	                        available += 1;
375	                    } else {
376	                        cooling += 1;
377	                    }
378	                }
379	                Some(AccountStatus::Disabled) | None => disabled += 1,
380	            }
381	        }
382	        (total, available, cooling, disabled)
383	    }
384	
385	    /// Build the exhausted error message JSON.
386	    async fn exhausted_message(
387	        &self,
388	        total: usize,
389	        available: usize,
390	        cooling: usize,
391	        disabled: usize,
392	    ) -> String {
393	        serde_json::json!({
394	            "error": {
395	                "type": "pool_exhausted",
396	                "message": "All accounts exhausted",
397	                "pool": {
398	                    "accounts_total": total,
399	                    "accounts_available": available,
400	                    "accounts_cooling_down": cooling,
401	                    "accounts_disabled": disabled
402	                }
403	            }
404	        })
405	        .to_string()
406	    }
407	}
408	
409	#[cfg(test)]
410	mod tests {
411	    use super::*;
412	    use anthropic_auth::Credential;
413	    use std::sync::Arc;
414	
415	    /// Create a credential store with test accounts.
416	    async fn test_store(dir: &tempfile::TempDir, accounts: &[(&str, u64)]) -> Arc<CredentialStore> {
417	        let path = dir.path().join("credentials.json");
418	        let store = CredentialStore::load(path).await.unwrap();
419	        for (id, expires) in accounts {
420	            store
421	                .add(
422	                    id.to_string(),
