1	//! Anthropic OAuth provider — pool-backed token injection and body modification.
2	//!
3	//! Implements the Provider trait using the subscription pool for account selection,
4	//! token injection, beta header merging, and system prompt injection. This is the
5	//! OAuth pool mode counterpart to PassthroughProvider.
6	
7	use anthropic_auth::REQUIRED_SYSTEM_PROMPT_PREFIX;
8	use anthropic_pool::Pool;
9	use provider::{ErrorClassification, Provider, ProviderError, ProviderHealth};
10	use reqwest::header::{HeaderMap, HeaderName, HeaderValue};
11	use std::future::Future;
12	use std::pin::Pin;
13	use std::sync::Arc;
14	use tracing::{debug, warn};
15	
16	/// Required anthropic-beta flags for OAuth mode. These are always injected and
17	/// merged with any client-provided beta flags (deduplicated).
18	const REQUIRED_BETA_FLAGS: &[&str] = &[
19	    "oauth-2025-04-20",
20	    "interleaved-thinking-2025-05-14",
21	    "context-management-2025-06-27",
22	];
23	
24	/// User-Agent captured from Claude CLI v2.0.76 `/v1/messages` traffic via
25	/// the Loom mitmproxy procedure; see `docs/audits/header-provenance.md`.
26	const USER_AGENT: &str = "claude-cli/2.0.76 (external, sdk-cli)";
27	
28	/// Anthropic API version header value.
29	const ANTHROPIC_VERSION: &str = "2023-06-01";
30	
31	/// Claude Code attribution header used by this proxy for Max-plan routing.
32	/// Origin: Claude Code `--debug-file` attribution line. `cc_version` tracks the
33	/// CC release (bumped to 2.1.158 on 2026-05-31 via `scripts/capture-cc-headers.sh`);
34	/// `cc_entrypoint=sdk-cli` is the headless path; `cch=00000` is a hardcoded CC
35	/// constant with no account data. Note: genuine CC does NOT send this header on
36	/// the `/v1/messages` wire (debug-only) — the proxy injects it deliberately and
37	/// it is accepted. See `docs/audits/header-provenance.md` before changing this.
38	const ANTHROPIC_BILLING_HEADER: &str = "cc_version=2.1.158.c5c; cc_entrypoint=sdk-cli; cch=00000;";
39	
40	/// OAuth provider backed by a subscription pool.
41	///
42	/// Selects accounts round-robin, injects Bearer tokens, merges anthropic-beta
43	/// flags, and injects the required system prompt prefix for all models.
44	pub struct AnthropicOAuthProvider {
45	    pool: Arc<Pool>,
46	}
47	
48	impl AnthropicOAuthProvider {
49	    pub fn new(pool: Arc<Pool>) -> Self {
50	        Self { pool }
51	    }
52	}
53	
54	impl Provider for AnthropicOAuthProvider {
55	    fn id(&self) -> &str {
56	        "anthropic"
57	    }
58	
59	    fn needs_body(&self) -> bool {
60	        true
61	    }
62	
63	    fn prepare_request<'a>(
64	        &'a self,
65	        headers: &'a mut HeaderMap,
66	        body: &'a mut serde_json::Value,
67	    ) -> Pin<Box<dyn Future<Output = provider::Result<Option<String>>> + Send + 'a>> {
68	        Box::pin(async move {
69	            let selected = self.pool.select().await.map_err(|e| match e {
70	                anthropic_pool::Error::PoolExhausted(msg) => ProviderError::PoolExhausted(msg),
71	                other => ProviderError::Internal(other.to_string()),
72	            })?;
73	
74	            // Strip any client-provided auth headers — OAuth mode manages its
75	            // own credentials. Both Authorization (Bearer) and x-api-key (direct
76	            // API key) must be removed. Forwarding x-api-key alongside the OAuth
77	            // Bearer token signals a non-Claude-Code client to Anthropic.
78	            headers.remove(reqwest::header::AUTHORIZATION);
79	            headers.remove(HeaderName::from_static("x-api-key"));
80	
81	            // Inject Bearer token from the selected account
82	            headers.insert(
83	                reqwest::header::AUTHORIZATION,
84	                HeaderValue::from_str(&format!("Bearer {}", selected.access_token))
85	                    .map_err(|e| ProviderError::Internal(format!("invalid token value: {e}")))?,
86	            );
87	
88	            // Merge anthropic-beta flags: combine required flags with any
89	            // client-provided flags, deduplicating.
90	            merge_beta_headers(headers);
91	
92	            // Inject required headers
93	            headers.insert(
94	                HeaderName::from_static("anthropic-dangerous-direct-browser-access"),
95	                HeaderValue::from_static("true"),
96	            );
97	            headers.insert(
98	                reqwest::header::USER_AGENT,
99	                HeaderValue::from_static(USER_AGENT),
100	            );
101	            headers.insert(
102	                HeaderName::from_static("anthropic-version"),
103	                HeaderValue::from_static(ANTHROPIC_VERSION),
104	            );
105	            headers.insert(
106	                HeaderName::from_static("x-anthropic-billing-header"),
107	                HeaderValue::from_static(ANTHROPIC_BILLING_HEADER),
108	            );
109	
110	            // System prompt injection for all models. Then remove Pi's local
111	            // documentation-routing hint, which trips Anthropic's Max-plan
112	            // usage classifier even with Claude Code attribution present.
113	            inject_system_prompt(body);
114	            sanitize_system_prompt_for_plan_usage(body);
115	
116	            Ok(Some(selected.id))
117	        })
118	    }
119	
120	    fn classify_error(&self, status: u16, body: &str) -> ErrorClassification {
121	        anthropic_pool::classify_status(status, body)
122	    }
123	
124	    fn report_error(
125	        &self,
126	        account_id: &str,
127	        classification: ErrorClassification,
128	    ) -> Pin<Box<dyn Future<Output = provider::Result<()>> + Send + '_>> {
129	        let account_id = account_id.to_string();
130	        Box::pin(async move {
131	            self.pool.report_error(&account_id, classification).await;
132	            Ok(())
133	        })
134	    }
