136	    fn health(&self) -> Pin<Box<dyn Future<Output = ProviderHealth> + Send + '_>> {
137	        Box::pin(async move {
138	            let pool_health = self.pool.health().await;
139	            let status = pool_health
140	                .get("status")
141	                .and_then(|s| s.as_str())
142	                .unwrap_or("unhealthy")
143	                .to_string();
144	            ProviderHealth {
145	                status,
146	                pool: Some(pool_health),
147	            }
148	        })
149	    }
