152	/// Merge required anthropic-beta flags with any client-provided flags.
153	///
154	/// Reads the existing `anthropic-beta` header, splits by comma, combines with
155	/// the required set, deduplicates, and writes back as a single comma-separated
156	/// header value.
157	fn merge_beta_headers(headers: &mut HeaderMap) {
158	    let mut flags: Vec<String> = REQUIRED_BETA_FLAGS.iter().map(|s| s.to_string()).collect();
159	
160	    if let Some(existing) = headers.get("anthropic-beta")
161	        && let Ok(existing_str) = existing.to_str()
162	    {
163	        for flag in existing_str.split(',') {
164	            let trimmed = flag.trim().to_string();
165	            if !trimmed.is_empty() && !flags.contains(&trimmed) {
166	                flags.push(trimmed);
167	            }
168	        }
169	    }
170	
171	    let merged = flags.join(",");
172	    match HeaderValue::from_str(&merged) {
173	        Ok(v) => {
174	            headers.insert(HeaderName::from_static("anthropic-beta"), v);
175	        }
176	        Err(e) => {
177	            warn!(error = %e, "failed to construct merged anthropic-beta header");
178	        }
179	    }
180	}
