182	/// Extract the model name from a request body JSON object.
183	fn extract_model(body: &serde_json::Value) -> Option<&str> {
184	    body.get("model").and_then(|m| m.as_str())
185	}
186	
187	/// Inject the required system prompt prefix for OAuth credential compliance.
188	///
189	/// The Anthropic API accepts `system` as either a plain string or an array of
190	/// content blocks (`[{"type":"text","text":"..."}]`). This function handles both.
191	///
192	/// Rules:
193	/// - No model field: skip (can't determine if injection is needed)
194	/// - No `system` field: create as array with required prefix block
195	/// - String `system` without prefix: convert to array, prepend prefix block
196	/// - String `system` with prefix: convert to array (preserve prefix)
197	/// - Array `system` whose first text block lacks prefix: prepend prefix block
198	/// - Array `system` already has prefix: no modification
199	///
200	/// The output is always an array of content blocks so that cache_control and
201	/// other per-block metadata survive round-tripping through the proxy.
202	///
203	/// Applied to ALL models including Haiku. While Haiku doesn't require the
204	/// prefix for model access, consistent injection avoids credential validation
205	/// edge cases. Loom (reference implementation) applies the prefix to all
206	/// models under OAuth.
207	fn sanitize_pi_documentation_block(text: &str) -> Option<String> {
208	    let marker = "\n\nPi documentation (read only when";
209	    let (prefix, rest) = text.split_once(marker)?;
210	    let retained_context: Vec<&str> = rest
211	        .lines()
212	        .filter(|line| {
213	            line.starts_with("Current date:") || line.starts_with("Current working directory:")
214	        })
215	        .collect();
216	
217	    let prefix = prefix.trim_end();
218	    if retained_context.is_empty() {
219	        Some(prefix.to_string())
220	    } else {
221	        Some(format!("{}\n\n{}", prefix, retained_context.join("\n")))
222	    }
223	}
224	
225	fn sanitize_system_prompt_for_plan_usage(body: &mut serde_json::Value) {
226	    match body.get_mut("system") {
227	        Some(system) if system.is_string() => {
228	            if let Some(text) = system.as_str().and_then(sanitize_pi_documentation_block) {
229	                *system = serde_json::Value::String(text);
230	            }
231	        }
232	        Some(system) if system.is_array() => {
233	            if let Some(blocks) = system.as_array_mut() {
234	                for block in blocks {
235	                    if block.get("type").and_then(|t| t.as_str()) == Some("text")
236	                        && let Some(text_value) = block.get_mut("text")
237	                        && let Some(text) = text_value
238	                            .as_str()
239	                            .and_then(sanitize_pi_documentation_block)
240	                    {
241	                        *text_value = serde_json::Value::String(text);
242	                    }
243	                }
244	            }
245	        }
246	        _ => {}
247	    }
248	}
249	
250	fn inject_system_prompt(body: &mut serde_json::Value) {
251	    if extract_model(body).is_none() {
252	        return;
253	    }
254	
255	    let prefix = REQUIRED_SYSTEM_PROMPT_PREFIX;
256	
257	    match body.get("system") {
258	        None => {
259	            body["system"] = serde_json::json!([
260	                { "type": "text", "text": prefix }
261	            ]);
262	            debug!("injected system prompt (no existing system field)");
263	        }
264	        Some(existing) if existing.is_string() => {
265	            let existing_str = existing.as_str().unwrap();
266	            if existing_str.starts_with(prefix) {
267	                // Already has prefix — convert to array preserving content
268	                body["system"] = serde_json::json!([
269	                    { "type": "text", "text": existing_str }
270	                ]);
271	            } else {
272	                // Prepend prefix as separate block, keep original as second block
273	                body["system"] = serde_json::json!([
274	                    { "type": "text", "text": prefix },
275	                    { "type": "text", "text": existing_str }
276	                ]);
277	                debug!("prepended system prompt prefix to existing string system field");
278	            }
279	        }
280	        Some(existing) if existing.is_array() => {
281	            let arr = existing.as_array().unwrap();
282	            // Check if the first text block already starts with the prefix
283	            let has_prefix = arr.iter().any(|block| {
284	                block.get("type").and_then(|t| t.as_str()) == Some("text")
285	                    && block
286	                        .get("text")
287	                        .and_then(|t| t.as_str())
288	                        .is_some_and(|t| t.starts_with(prefix))
289	            });
290	            if !has_prefix {
291	                let mut new_arr = vec![serde_json::json!({ "type": "text", "text": prefix })];
292	                new_arr.extend(arr.iter().cloned());
293	                body["system"] = serde_json::Value::Array(new_arr);
294	                debug!("prepended system prompt prefix to existing array system field");
295	            }
296	        }
297	        _ => {
298	            // Non-string, non-array system field: leave as-is
299	        }
300	    }
301	}
