    async fn test_store(dir: &tempfile::TempDir, accounts: &[(&str, u64)]) -> Arc<CredentialStore> {
        let path = dir.path().join("credentials.json");
        let store = CredentialStore::load(path).await.unwrap();
        for (id, expires) in accounts {
