1	//! Pool state machine and round-robin account selection
2	//!
3	//! The pool holds per-account status (Available, CoolingDown, Disabled) and selects
4	//! accounts round-robin. The credential store is the single source of truth for
5	//! token data; the pool reads credentials at selection time.
6	//!
7	//! Cooldown transitions happen automatically: when a CoolingDown account is checked
8	//! and its cooldown has expired, it transitions back to Available without explicit action.
9	
10	use std::collections::HashMap;
11	use std::sync::atomic::{AtomicUsize, Ordering};
12	use std::time::{Duration, Instant};
13	
14	use anthropic_auth::CredentialStore;
15	use provider::ErrorClassification;
16	use tokio::sync::RwLock;
17	use tracing::{debug, info, warn};
18	
19	use crate::error::{Error, Result};
20	
21	/// Runtime status of a pool account.
22	///
23	/// Transitions:
24	/// - Available → CoolingDown (quota exhausted 429)
25	/// - Available → Disabled (401/403 permanent error)
26	/// - CoolingDown → Available (cooldown expired)
27	/// - CoolingDown → Disabled (refresh failure while cooling)
28	/// - Disabled → (removed by admin)
29	#[derive(Debug, Clone)]
30	pub enum AccountStatus {
31	    Available,
32	    CoolingDown { until: Instant },
33	    Disabled,
34	}
35	
36	impl AccountStatus {
37	    /// Status label for health/logging.
38	    pub fn label(&self) -> &'static str {
39	        match self {
40	            AccountStatus::Available => "available",
41	            AccountStatus::CoolingDown { .. } => "cooling_down",
42	            AccountStatus::Disabled => "disabled",
43	        }
44	    }
45	}
46	
47	/// A selected account with its access token, ready for a request.
48	#[derive(Debug)]
49	pub struct SelectedAccount {
50	    pub id: String,
51	    pub access_token: String,
52	}
53	
54	/// Subscription pool managing multiple OAuth accounts.
55	///
56	/// Uses an `AtomicUsize` for the round-robin index and `RwLock` for the account
57	/// list and status map. The credential store is shared via `Arc` and provides
58	/// the token data.
59	pub struct Pool {
60	    account_ids: RwLock<Vec<String>>,
61	    statuses: RwLock<HashMap<String, AccountStatus>>,
62	    next_index: AtomicUsize,
63	    cooldown_duration: Duration,
64	    credential_store: std::sync::Arc<CredentialStore>,
65	    http_client: reqwest::Client,
66	}
67	
68	/// Whether a token-refresh failure is permanent (the refresh token is revoked or
69	/// invalid) versus transient (network blip, 5xx, rate-limit).
70	///
71	/// Permanent failures disable the account; transient failures leave it Available
72	/// so a later request or the background refresh task can retry. This mirrors the
73	/// background refresh task's classification so the inline and background paths
74	/// agree on what counts as fatal.
75	fn refresh_failure_is_permanent(err: &anthropic_auth::Error) -> bool {
76	    matches!(err, anthropic_auth::Error::InvalidCredentials(_))
77	}
78	
79	impl Pool {
80	    /// Create a new pool backed by the given credential store.
81	    ///
82	    /// `account_ids` is the initial list of accounts to manage. Each must have
83	    /// a corresponding entry in the credential store. Accounts start as Available.
84	    pub fn new(
85	        account_ids: Vec<String>,
86	        cooldown_duration: Duration,
87	        credential_store: std::sync::Arc<CredentialStore>,
88	        http_client: reqwest::Client,
89	    ) -> Self {
90	        let statuses: HashMap<String, AccountStatus> = account_ids
91	            .iter()
92	            .map(|id| (id.clone(), AccountStatus::Available))
93	            .collect();
94	        info!(accounts = account_ids.len(), "pool initialized");
95	        Self {
96	            account_ids: RwLock::new(account_ids),
97	            statuses: RwLock::new(statuses),
98	            next_index: AtomicUsize::new(0),
99	            cooldown_duration,
100	            credential_store,
101	            http_client,
102	        }
103	    }
104	
105	    /// Select the next available account via round-robin.
106	    ///
107	    /// Scans all accounts starting from `next_index`. Expired cooldowns are
108	    /// transitioned to Available automatically. If a selected account's token
109	    /// expires within 60 seconds, attempts an inline refresh; on failure, the
110	    /// account is disabled and the scan continues.
111	    ///
112	    /// Returns `PoolExhausted` with pool counts if no account is available.
113	    pub async fn select(&self) -> Result<SelectedAccount> {
114	        let ids = self.account_ids.read().await;
115	        let n = ids.len();
116	        if n == 0 {
117	            return Err(Error::PoolExhausted(
118	                self.exhausted_message(0, 0, 0, 0).await,
119	            ));
120	        }
121	
122	        let start = self.next_index.fetch_add(1, Ordering::Relaxed) % n;
123	
124	        for offset in 0..n {
125	            let idx = (start + offset) % n;
126	            let id = &ids[idx];
127	
128	            // Check and possibly transition status
129	            let available = {
130	                let mut statuses = self.statuses.write().await;
131	                let status = statuses.get(id);
132	                match status {
133	                    Some(AccountStatus::Available) => true,
134	                    Some(AccountStatus::CoolingDown { until }) => {
135	                        if Instant::now() >= *until {
136	                            info!(account_id = id, "cooldown expired, account available again");
137	                            statuses.insert(id.clone(), AccountStatus::Available);
138	                            true
139	                        } else {
140	                            false
141	                        }
142	                    }
143	                    Some(AccountStatus::Disabled) | None => false,
144	                }
145	            };
146	
147	            if !available {
148	                continue;
149	            }
150	
151	            // Get credential from store
152	            let credential = match self.credential_store.get(id).await {
153	                Some(c) => c,
154	                None => {
155	                    warn!(
156	                        account_id = id,
157	                        "account in pool but not in credential store, disabling"
158	                    );
159	                    self.statuses
160	                        .write()
161	                        .await
162	                        .insert(id.clone(), AccountStatus::Disabled);
163	                    continue;
164	                }
165	            };
166	
167	            // Request-time refresh: if token expires within 60 seconds, refresh inline
168	            let now_millis = std::time::SystemTime::now()
169	                .duration_since(std::time::UNIX_EPOCH)
170	                .unwrap_or_default()
171	                .as_millis() as u64;
172	            let refresh_threshold_millis = 60_000;
173	
174	            if credential.expires <= now_millis + refresh_threshold_millis {
175	                debug!(
176	                    account_id = id,
177	                    "token expiring soon, attempting inline refresh"
178	                );
179	                match anthropic_auth::refresh_token(&self.http_client, &credential.refresh).await {
180	                    Ok(token_response) => {
181	                        let new_expires = now_millis + (token_response.expires_in * 1000);
182	                        if let Err(e) = self
183	                            .credential_store
184	                            .update_token(
185	                                id,
186	                                token_response.access_token.clone(),
187	                                token_response.refresh_token,
188	                                new_expires,
189	                            )
190	                            .await
191	                        {
192	                            warn!(account_id = id, error = %e, "failed to persist refreshed token");
193	                        }
194	                        info!(account_id = id, "inline token refresh succeeded");

